package com.example.starter.incident;

/**
 * 处置任务状态机：OPEN → STARTED → DONE，或 OPEN → DONE（无安排时），
 * 或 OPEN → CANCELLED、STARTED → CANCELLED。
 * DONE 与 CANCELLED 均为终态，不允许任何后续流转；取消仅适用于 OPEN 与 STARTED。
 * 有执行安排的任务必须经 STARTED 才能 DONE；STARTED 任务的安排不可变更。
 */
public enum TaskStatus {

    /** 待处理。 */
    OPEN,

    /** 已开始（须存在执行安排且开始时刻落在安排区间内、阻塞已解除）。 */
    STARTED,

    /** 已完成（要求全部阻塞事件已进入 CONTAINED/RESOLVED/CLOSED；有安排的任务须先开始）。 */
    DONE,

    /** 已取消。 */
    CANCELLED;
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 任务执行安排实体，对应 task_assignments 表。
 * 每任务至多一条当前安排（taskId 唯一），替换即更新本行；
 * 绑定合成人员 assignee 与 UTC 整分钟左闭右开时段 [startAt, endAt)，时长 1~240 分钟。
 * 同一人员的全部安排不重叠，相邻安排至少休息 30 分钟；
 * 每 UTC 日与当日相交的作业总量不超过 480 分钟，跨午夜按交集拆日。
 * 任务未开始被取消时删除本行释放时段；已开始任务的完成/取消保留本行，不释放休息约束。
 */
public record TaskAssignment(
        long id,
        long taskId,
        String assignee,
        Instant startAt,
        Instant endAt,
        String createdBy,
        Instant createdAt,
        Instant updatedAt) {

    /**
     * 时段长度（分钟），左闭右开。
     */
    public long durationMinutes() {
        return java.time.Duration.between(startAt, endAt).toMinutes();
    }
}

