121	    /**
122	     * 事件上报：初始状态 REPORTED，无指挥人。incidentKey 重复返回 409。
123	     */
124	    @Transactional
125	    public IncidentView report(ReportRequest req) {
126	        String incidentKey = requireText(req.incidentKey(), "incidentKey");
127	        String severity = requireText(req.severity(), "severity");
128	        if (!severity.matches("S[1-4]")) {
129	            throw ApiException.badRequest("severity 必须为 S1~S4");
130	        }
131	        String summary = requireText(req.summary(), "summary");
132	        String reporter = requireText(req.reporter(), "reporter");
133	        if (incidents.findByKey(incidentKey).isPresent()) {
134	            throw ApiException.conflict("incidentKey 已存在: " + incidentKey);
135	        }
136	        Instant now = now();
137	        Incident incident = new Incident(0L, incidentKey, severity, summary, reporter,
138	                IncidentStatus.REPORTED, null, now, now, null);
139	        long id;
140	        try {
141	            id = incidents.insert(incident);
142	        } catch (DuplicateKeyException e) {
143	            throw ApiException.conflict("incidentKey 已存在: " + incidentKey);
144	        }
145	        incidents.insertStatusChange(new StatusChange(0L, id, null, IncidentStatus.REPORTED, reporter, now));
146	        return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
147	    }
