149	    /**
150	     * 首次接管：REPORTED → COMMANDING，记录当前指挥人，
151	     * 并以该次接管 UTC 时刻按等级确定遏制期限（只写一次，交接不重置）。
152	     */
153	    @Transactional
154	    public IncidentView takeover(String incidentKey, String actor, TakeoverRequest req) {
155	        String commandKey = requireText(req.commandKey(), "commandKey");
156	        Incident incident = lockIncident(incidentKey);
157	        return runIdempotent(commandKey, "takeover", hash(incidentKey, actor), IncidentView.class,
158	                () -> {
159	                    if (incident.status() != IncidentStatus.REPORTED) {
160	                        throw ApiException.illegalTransition(
161	                                "仅 REPORTED 状态可接管，当前状态: " + incident.status());
162	                    }
163	                    Instant now = now();
164	                    Instant deadline = now.plus(CONTAINMENT_MINUTES.get(incident.severity()),
165	                            ChronoUnit.MINUTES);
166	                    incidents.updateState(incident.id(), IncidentStatus.COMMANDING, actor, now);
167	                    incidents.updateDeadline(incident.id(), deadline, now);
168	                    incidents.insertStatusChange(new StatusChange(0L, incident.id(),
169	                            IncidentStatus.REPORTED, IncidentStatus.COMMANDING, actor, now));
170	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
171	                });
172	    }
