174	    /**
175	     * 发起交接：仅当前指挥人可发起，目标人必须不同；RESOLVED/CLOSED 禁止发起。
176	     */
177	    @Transactional
178	    public TransferView initiateTransfer(String incidentKey, String actor, TransferRequest req) {
179	        String commandKey = requireText(req.commandKey(), "commandKey");
180	        String toCommander = requireText(req.toCommander(), "toCommander");
181	        Incident incident = lockIncident(incidentKey);
182	        return runIdempotent(commandKey, "transfer_initiate", hash(incidentKey, actor, toCommander),
183	                TransferView.class, () -> {
184	                    requireCommander(incident, actor);
185	                    if (incident.status() == IncidentStatus.RESOLVED
186	                            || incident.status() == IncidentStatus.CLOSED) {
187	                        throw ApiException.illegalTransition(
188	                                incident.status() + " 状态不允许发起交接");
189	                    }
190	                    if (incident.status() == IncidentStatus.REPORTED) {
191	                        throw ApiException.illegalTransition("尚未接管的事件不能发起交接");
192	                    }
193	                    if (toCommander.equals(incident.commander())) {
194	                        throw ApiException.badRequest("目标指挥人必须与当前指挥人不同");
195	                    }
196	                    if (incidents.findPendingTransfer(incident.id()).isPresent()) {
197	                        throw ApiException.conflict("已存在待接受的交接，不能重复发起");
198	                    }
199	                    Instant now = now();
200	                    incidents.insertTransfer(new IncidentTransfer(0L, incident.id(),
201	                            incident.commander(), toCommander, TransferStatus.PENDING, now, null));
202	                    return toTransferView(incidents.findPendingTransfer(incident.id()).orElseThrow());
203	                });
204	    }
205	
206	    /**
207	     * 接受交接：仅待接受目标人可接受；接受后原子切换当前指挥人。
208	     * RESOLVED/CLOSED 禁止接受；待接受期间目标人无其他操作权限。
209	     */
210	    @Transactional
211	    public IncidentView acceptTransfer(String incidentKey, String actor, TransferAcceptRequest req) {
212	        String commandKey = requireText(req.commandKey(), "commandKey");
213	        Incident incident = lockIncident(incidentKey);
214	        return runIdempotent(commandKey, "transfer_accept", hash(incidentKey, actor), IncidentView.class,
215	                () -> {
216	                    if (incident.status() == IncidentStatus.RESOLVED
217	                            || incident.status() == IncidentStatus.CLOSED) {
218	                        throw ApiException.illegalTransition(
219	                                incident.status() + " 状态不允许接受交接");
220	                    }
221	                    IncidentTransfer pending = incidents.findPendingTransfer(incident.id())
222	                            .orElseThrow(() -> ApiException.conflict("当前没有待接受的交接"));
223	                    if (!pending.toCommander().equals(actor)) {
224	                        throw ApiException.conflict("只有交接目标人 " + pending.toCommander() + " 能接受交接");
225	                    }
226	                    Instant now = now();
227	                    incidents.acceptTransfer(pending.id(), now);
228	                    incidents.updateState(incident.id(), incident.status(), pending.toCommander(), now);
229	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
230	                });
231	    }
