233	    /**
234	     * 追加处置记录：仅当前指挥人可写；CLOSED 后禁止写入。
235	     * actionKey 事件内唯一：同键同内容幂等返回首次记录，同键不同内容返回 409。
236	     */
237	    @Transactional
238	    public ActionView addAction(String incidentKey, String actor, ActionRequest req) {
239	        String commandKey = requireText(req.commandKey(), "commandKey");
240	        String actionKey = requireText(req.actionKey(), "actionKey");
241	        String actionType = requireText(req.actionType(), "actionType");
242	        String note = requireText(req.note(), "note");
243	        if (req.occurredAt() == null) {
244	            throw ApiException.badRequest("occurredAt 不能为空");
245	        }
246	        Instant occurredAt = req.occurredAt().truncatedTo(ChronoUnit.MICROS);
247	        Incident incident = lockIncident(incidentKey);
248	        return runIdempotent(commandKey, "action",
249	                hash(incidentKey, actor, actionKey, actionType, note, occurredAt.toString()),
250	                ActionView.class, () -> {
251	                    requireCommander(incident, actor);
252	                    if (incident.status() == IncidentStatus.CLOSED) {
253	                        throw ApiException.illegalTransition("事件已关闭，不能再追加处置记录");
254	                    }
255	                    var existing = incidents.findAction(incident.id(), actionKey);
256	                    if (existing.isPresent()) {
257	                        IncidentAction found = existing.get();
258	                        if (!found.sameContent(actionType, note, occurredAt)) {
259	                            throw ApiException.conflict("actionKey 已被不同内容使用: " + actionKey);
260	                        }
261	                        return toActionView(found);
262	                    }
263	                    Instant now = now();
264	                    incidents.insertAction(new IncidentAction(0L, incident.id(), actionKey, actionType,
265	                            note, occurredAt, actor, now));
266	                    return toActionView(incidents.findAction(incident.id(), actionKey).orElseThrow());
267	                });
268	    }
269	
270	    /**
271	     * 状态变更：仅当前指挥人可操作，仅允许 COMMANDING→CONTAINED→RESOLVED→CLOSED 逐级前进。
272	     * 进入 CONTAINED 时同事务将仍 OPEN 的逾期升级记录原子置为 CANCELLED，已确认记录保留。
273	     */
274	    @Transactional
275	    public IncidentView changeStatus(String incidentKey, String actor, StatusRequest req) {
276	        String commandKey = requireText(req.commandKey(), "commandKey");
277	        String target = requireText(req.targetStatus(), "targetStatus");
278	        IncidentStatus targetStatus;
279	        try {
280	            targetStatus = IncidentStatus.valueOf(target);
281	        } catch (IllegalArgumentException e) {
282	            throw ApiException.badRequest("未知目标状态: " + target);
283	        }
284	        Incident incident = lockIncident(incidentKey);
285	        return runIdempotent(commandKey, "status", hash(incidentKey, actor, target),
286	                IncidentView.class, () -> {
287	                    requireCommander(incident, actor);
288	                    IncidentStatus next = incident.status().next();
289	                    if (next == null || next != targetStatus) {
290	                        throw ApiException.illegalTransition(
291	                                "不允许从 " + incident.status() + " 流转到 " + targetStatus);
292	                    }
293	                    if (targetStatus == IncidentStatus.RESOLVED) {
294	                        // 解决门禁：全部处置任务进入 DONE/CANCELLED 后才可解决
295	                        List<UnfinishedTaskView> unfinished = tasks
296	                                .listOpenByIncident(incident.id()).stream()
297	                                .map(t -> new UnfinishedTaskView(t.groupCode(), t.taskKey()))
298	                                .toList();
299	                        if (!unfinished.isEmpty()) {
300	                            throw ApiException.conflict(
301	                                    "仍有未完成的处置任务，不能进入 RESOLVED", unfinished);
302	                        }
303	                    }
304	                    Instant now = now();
305	                    incidents.updateState(incident.id(), targetStatus, incident.commander(), now);
306	                    incidents.insertStatusChange(new StatusChange(0L, incident.id(),
307	                            incident.status(), targetStatus, actor, now));
308	                    if (targetStatus == IncidentStatus.CONTAINED) {
309	                        escalations.cancelOpenForIncident(incident.id(), now);
310	                    }
311	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
312	                });
313	    }
