315	    /**
316	     * 单事件遏制逾期检查：以注入 Clock 的当前时刻评估，不做定时扫描。
317	     * 仅当事件仍为 COMMANDING、尚无升级记录且当前时刻 ≥ 接管时确定的期限时，
318	     * 追加一条 OPEN 记录（保存期限、触发时刻、当时指挥人），每事件至多一条。
319	     * 期限前或其他状态不产生记录；同键重放首次结果（含期限前的无记录结果），
320	     * 失败不占键；需要重新评估必须更换 commandKey。
321	     */
322	    @Transactional
323	    public EscalationHistoryView checkEscalation(String incidentKey, EscalationCheckRequest req) {
324	        String commandKey = requireText(req.commandKey(), "commandKey");
325	        Incident incident = lockIncident(incidentKey);
326	        return runIdempotent(commandKey, "escalation_check", hash(incidentKey),
327	                EscalationHistoryView.class, () -> {
328	                    var existing = escalations.findByIncident(incident.id());
329	                    if (existing.isPresent()) {
330	                        return toEscalationHistory(incident, List.of(existing.get()));
331	                    }
332	                    Instant currentTime = now();
333	                    if (incident.status() == IncidentStatus.COMMANDING
334	                            && incident.deadlineAt() != null
335	                            && !currentTime.isBefore(incident.deadlineAt())) {
336	                        escalations.insert(new Escalation(0L, incident.id(), incident.deadlineAt(),
337	                                currentTime, incident.commander(), EscalationStatus.OPEN,
338	                                null, null, null, currentTime, currentTime));
339	                    }
340	                    return toEscalationHistory(incident,
341	                            escalations.listByIncident(incident.id()));
342	                });
343	    }
