345	    /**
346	     * 确认 OPEN 升级记录：仅操作当时的当前指挥人可确认（待接受期间目标人无确认权，
347	     * 交接接受后旧指挥人失去确认权），提交非空处置说明后进入 ACKNOWLEDGED，
348	     * 记录确认人与 UTC 时刻。已 CANCELLED/ACKNOWLEDGED 或不存在记录均为 409。
349	     */
350	    @Transactional
351	    public EscalationView acknowledgeEscalation(String incidentKey, String actor,
352	                                                EscalationAckRequest req) {
353	        String commandKey = requireText(req.commandKey(), "commandKey");
354	        String note = requireText(req.note(), "note");
355	        Incident incident = lockIncident(incidentKey);
356	        return runIdempotent(commandKey, "escalation_ack", hash(incidentKey, actor, note),
357	                EscalationView.class, () -> {
358	                    requireCommander(incident, actor);
359	                    Escalation escalation = escalations.findByIncident(incident.id())
360	                            .orElseThrow(() -> ApiException.conflict("当前没有可确认的升级记录"));
361	                    if (escalation.status() != EscalationStatus.OPEN) {
362	                        throw ApiException.conflict(
363	                                "升级记录状态为 " + escalation.status() + "，不能确认");
364	                    }
365	                    Instant ackedAt = now();
366	                    int updated = escalations.acknowledge(escalation.id(), note, actor, ackedAt);
367	                    if (updated == 0) {
368	                        throw ApiException.conflict("升级记录已被并发处理，不能确认");
369	                    }
370	                    return toEscalationView(
371	                            escalations.findByIncident(incident.id()).orElseThrow());
372	                });
373	    }
