397	    /**
398	     * 查询完整历史：事件本体、状态流转、处置记录、交接记录、升级记录。
399	     */
400	    @Transactional(readOnly = true)
401	    public HistoryView history(String incidentKey) {
402	        Incident incident = incidents.findByKey(incidentKey)
403	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
404	        String pendingTo = incidents.findPendingTransfer(incident.id())
405	                .map(IncidentTransfer::toCommander).orElse(null);
406	        List<StatusChangeView> statusHistory = incidents.listStatusHistory(incident.id()).stream()
407	                .map(s -> new StatusChangeView(
408	                        s.fromStatus() == null ? null : s.fromStatus().name(),
409	                        s.toStatus().name(), s.actor(), s.occurredAt()))
410	                .toList();
411	        List<ActionView> actions = incidents.listActions(incident.id()).stream()
412	                .map(this::toActionView).toList();
413	        List<TransferView> transfers = incidents.listTransfers(incident.id()).stream()
414	                .map(IncidentService::toTransferView).toList();
415	        List<EscalationView> escalationList = escalations.listByIncident(incident.id()).stream()
416	                .map(this::toEscalationView).toList();
417	        return new HistoryView(toView(incident, pendingTo), statusHistory, actions, transfers,
418	                escalationList);
