421	    /**
422	     * 创建处置任务：仅当前指挥人；taskKey 事件内唯一；阻塞事件 0~5 个、必须存在且非自身；
423	     * 创建时在依赖图全局锁内做环检测，拒绝直接或间接环（409 且不留部分任务或边）。
424	     * taskKey 幂等：同键同内容（含阻塞集合）返回首次任务，同键不同内容返回 409。
425	     */
426	    @Transactional
427	    public TaskView createTask(String incidentKey, String actor, TaskCreateRequest req) {
428	        String commandKey = requireText(req.commandKey(), "commandKey");
429	        String taskKey = requireText(req.taskKey(), "taskKey");
430	        String groupCode = requireText(req.groupCode(), "groupCode");
431	        String title = requireText(req.title(), "title");
432	        List<String> blockerKeys = req.blockerIncidentKeys() == null ? List.of()
433	                : req.blockerIncidentKeys().stream()
434	                        .map(k -> requireText(k, "blockerIncidentKey"))
435	                        .distinct()
436	                        .toList();
437	        if (blockerKeys.size() > MAX_BLOCKERS_PER_TASK) {
438	            throw ApiException.badRequest("阻塞事件最多 " + MAX_BLOCKERS_PER_TASK + " 个");
439	        }
440	        if (blockerKeys.contains(incidentKey)) {
441	            throw ApiException.badRequest("阻塞事件不能是事件自身: " + incidentKey);
442	        }
443	        Incident incident = lockIncident(incidentKey);
444	        return runIdempotent(commandKey, "task_create",
445	                hash(incidentKey, actor, taskKey, groupCode, title, String.join(",", blockerKeys)),
446	                TaskView.class, () -> {
447	                    requireCommander(incident, actor);
448	                    if (incident.status() == IncidentStatus.CLOSED) {
449	                        throw ApiException.illegalTransition("事件已关闭，不能再创建处置任务");
450	                    }
451	                    var existing = tasks.findByKey(incident.id(), taskKey);
452	                    if (existing.isPresent()) {
453	                        IncidentTask found = existing.get();
454	                        List<String> existingBlockers = incidents.listBlockingIncidents(found.id())
455	                                .stream().map(Incident::incidentKey).sorted().toList();
456	                        List<String> requested = blockerKeys.stream().sorted().toList();
457	                        if (!found.sameContent(groupCode, title)
458	                                || !existingBlockers.equals(requested)) {
459	                            throw ApiException.conflict("taskKey 已被不同内容使用: " + taskKey);
460	                        }
461	                        return toTaskView(found);
462	                    }
463	                    if (tasks.countByIncident(incident.id()) >= MAX_TASKS_PER_INCIDENT) {
464	                        throw ApiException.conflict("每个事件最多创建 " + MAX_TASKS_PER_INCIDENT
465	                                + " 个处置任务");
466	                    }
467	                    List<Incident> blockers = new ArrayList<>();
468	                    for (String blockerKey : blockerKeys) {
469	                        blockers.add(incidents.findByKey(blockerKey)
470	                                .orElseThrow(() -> ApiException.notFound(
471	                                        "阻塞事件不存在: " + blockerKey)));
472	                    }
473	                    // 全局图锁：串行化环检测与边写入，并发反向依赖下最终图无环
474	                    tasks.lockGraph();
475	                    for (Incident blocker : blockers) {
476	                        if (tasks.isReachable(blocker.id(), incident.id())) {
477	                            throw ApiException.conflict("阻塞关系会形成环: "
478	                                    + blocker.incidentKey() + " 已直接或间接依赖 " + incidentKey);
479	                        }
480	                    }
481	                    Instant now = now();
482	                    long taskId = tasks.insert(new IncidentTask(0L, incident.id(), taskKey,
483	                            groupCode, title, TaskStatus.OPEN, actor, null, null, null, null,
484	                            now, now));
485	                    for (Incident blocker : blockers) {
486	                        tasks.insertBlocker(taskId, blocker.id(), now);
487	                    }
488	                    return toTaskView(tasks.findByKey(incident.id(), taskKey).orElseThrow());
489	                });
490	    }
