492	    /**
493	     * 完成任务：仅当前指挥人；仅 OPEN 可完成；全部阻塞事件进入
494	     * CONTAINED/RESOLVED/CLOSED 后才可完成，否则 409 并返回未解除事件列表。
495	     * DONE/CANCELLED 为终态，重复操作按 commandKey 幂等规则返回首次结果。
496	     */
497	    @Transactional
498	    public TaskView completeTask(String incidentKey, String taskKey, String actor,
499	                                 TaskActionRequest req) {
500	        String commandKey = requireText(req.commandKey(), "commandKey");
501	        Incident incident = lockIncident(incidentKey);
502	        return runIdempotent(commandKey, "task_complete", hash(incidentKey, taskKey, actor),
503	                TaskView.class, () -> {
504	                    requireCommander(incident, actor);
505	                    IncidentTask task = tasks.findByKey(incident.id(), taskKey)
506	                            .orElseThrow(() -> ApiException.notFound("任务不存在: " + taskKey));
507	                    if (task.status() != TaskStatus.OPEN) {
508	                        throw ApiException.conflict(
509	                                "任务已处于终态 " + task.status() + "，不能完成");
510	                    }
511	                    List<String> unresolved = unresolvedBlockers(task.id());
512	                    if (!unresolved.isEmpty()) {
513	                        throw ApiException.conflict("存在未解除阻塞的事件: "
514	                                + String.join(",", unresolved), List.copyOf(unresolved));
515	                    }
516	                    tasks.markDone(task.id(), actor, now());
517	                    return toTaskView(tasks.findByKey(incident.id(), taskKey).orElseThrow());
518	                });
519	    }
520	
521	    /**
522	     * 取消任务：仅当前指挥人；仅 OPEN 可取消；DONE/CANCELLED 为终态，
523	     * 重复操作按 commandKey 幂等规则返回首次结果。
524	     */
525	    @Transactional
526	    public TaskView cancelTask(String incidentKey, String taskKey, String actor,
527	                               TaskActionRequest req) {
528	        String commandKey = requireText(req.commandKey(), "commandKey");
529	        Incident incident = lockIncident(incidentKey);
530	        return runIdempotent(commandKey, "task_cancel", hash(incidentKey, taskKey, actor),
531	                TaskView.class, () -> {
532	                    requireCommander(incident, actor);
533	                    IncidentTask task = tasks.findByKey(incident.id(), taskKey)
534	                            .orElseThrow(() -> ApiException.notFound("任务不存在: " + taskKey));
535	                    if (task.status() != TaskStatus.OPEN) {
536	                        throw ApiException.conflict(
537	                                "任务已处于终态 " + task.status() + "，不能取消");
538	                    }
539	                    tasks.markCancelled(task.id(), actor, now());
540	                    return toTaskView(tasks.findByKey(incident.id(), taskKey).orElseThrow());
541	                });
542	    }
543	
544	    /**
545	     * 按事件分组查询任务（含阻塞状态，按目标事件当前状态计算）。只读，不隐式写入。
546	     */
547	    @Transactional(readOnly = true)
548	    public IncidentTasksView listTasks(String incidentKey) {
549	        Incident incident = incidents.findByKey(incidentKey)
550	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
551	        List<TaskView> views = tasks.listByIncident(incident.id()).stream()
552	                .map(this::toTaskView).toList();
553	        return new IncidentTasksView(incident.incidentKey(), views);
554	    }
555	
556	    /**
557	     * 查询单任务明细（含阻塞状态）。只读，不隐式写入。
558	     */
559	    @Transactional(readOnly = true)
560	    public TaskView getTask(String incidentKey, String taskKey) {
561	        Incident incident = incidents.findByKey(incidentKey)
562	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
563	        IncidentTask task = tasks.findByKey(incident.id(), taskKey)
564	                .orElseThrow(() -> ApiException.notFound("任务不存在: " + taskKey));
565	        return toTaskView(task);
566	    }
567	
568	    /**
569	     * 仍未解除阻塞的事件键列表：目标事件未进入 CONTAINED/RESOLVED/CLOSED 即未解除。
570	     */
571	    private List<String> unresolvedBlockers(long taskId) {
572	        return incidents.listBlockingIncidents(taskId).stream()
573	                .filter(b -> !UNBLOCKING_STATUSES.contains(b.status()))
574	                .map(Incident::incidentKey)
575	                .toList();
576	    }
577	
578	    private Incident lockIncident(String incidentKey) {
579	        requireText(incidentKey, "incidentKey");
580	        return incidents.lockByKey(incidentKey)
581	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
582	    }
583	
584	    private static void requireCommander(Incident incident, String actor) {
585	        if (incident.commander() == null || !incident.commander().equals(actor)) {
586	            throw ApiException.conflict("只有当前指挥人 "
587	                    + (incident.commander() == null ? "(无)" : incident.commander()) + " 能执行该操作");
588	        }
589	    }
590	
591	    private static String requireText(String value, String field) {
592	        if (value == null || value.isBlank()) {
593	            throw ApiException.badRequest(field + " 不能为空");
594	        }
595	        return value.strip();
596	    }
597	
598	    /**
599	     * 幂等执行：同键同参重放首次响应，同键改参 409；并发同键由唯一约束串行化。
600	     */
601	    private <T> T runIdempotent(String commandKey, String operation, String requestHash,
602	                                Class<T> type, Supplier<T> business) {
603	        var existing = commandKeys.find(commandKey);
604	        if (existing.isPresent()) {
605	            return replay(existing.get(), operation, requestHash, type);
606	        }
607	        try {
608	            commandKeys.insertPlaceholder(commandKey, operation, requestHash, now());
609	        } catch (DuplicateKeyException e) {
610	            var committed = commandKeys.findForUpdate(commandKey)
611	                    .orElseThrow(() -> ApiException.conflict("commandKey 处理冲突: " + commandKey));
612	            return replay(committed, operation, requestHash, type);
613	        }
614	        T result = business.get();
615	        commandKeys.fillResponse(commandKey, 200, toJson(result));
616	        return result;
617	    }
618	
619	    private <T> T replay(CommandKeyRecord record, String operation, String requestHash, Class<T> type) {
620	        if (!record.operation().equals(operation) || !record.requestHash().equals(requestHash)) {
621	            throw ApiException.conflict("commandKey 已被不同参数的请求使用: " + record.commandKey());
622	        }
623	        if (record.responseBody() == null) {
624	            throw ApiException.conflict("commandKey 正在处理中: " + record.commandKey());
625	        }
626	        try {
627	            return objectMapper.readValue(record.responseBody(), type);
628	        } catch (JsonProcessingException e) {
629	            throw new IllegalStateException("幂等响应反序列化失败", e);
630	        }
631	    }
632	
633	    private String toJson(Object value) {
634	        try {
635	            return objectMapper.writeValueAsString(value);
636	        } catch (JsonProcessingException e) {
637	            throw new IllegalStateException("响应序列化失败", e);
638	        }
639	    }
640	
641	    private static String hash(String... parts) {
642	        try {
643	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
644	            byte[] out = digest.digest(String.join(SEP, parts).getBytes(StandardCharsets.UTF_8));
645	            return HexFormat.of().formatHex(out);
646	        } catch (NoSuchAlgorithmException e) {
647	            throw new IllegalStateException(e);
648	        }
649	    }
650	
651	    private IncidentView toView(Incident incident, String pendingTransferTo) {
652	        return new IncidentView(incident.incidentKey(), incident.severity(), incident.summary(),
653	                incident.reporter(), incident.status().name(), incident.commander(), pendingTransferTo,
654	                incident.createdAt(), incident.updatedAt(), incident.deadlineAt());
655	    }
656	
657	    private ActionView toActionView(IncidentAction action) {
658	        return new ActionView(action.actionKey(), action.actionType(), action.note(),
659	                action.occurredAt(), action.actor(), action.createdAt());
660	    }
661	
662	    /**
663	     * 组装任务视图：阻塞状态按目标事件查询时的当前状态计算，不写回依赖任务。
664	     */
665	    private TaskView toTaskView(IncidentTask task) {
666	        List<TaskBlockerView> blockers = incidents.listBlockingIncidents(task.id()).stream()
667	                .map(b -> new TaskBlockerView(b.incidentKey(), b.status().name(),
668	                        UNBLOCKING_STATUSES.contains(b.status())))
669	                .toList();
670	        return new TaskView(task.taskKey(), task.groupCode(), task.title(), task.status().name(),
671	                blockers, task.createdBy(), task.createdAt(), task.doneBy(), task.doneAt(),
672	                task.cancelledBy(), task.cancelledAt());
673	    }
674	
675	    private static TransferView toTransferView(IncidentTransfer transfer) {
676	        return new TransferView(transfer.id(), transfer.fromCommander(), transfer.toCommander(),
677	                transfer.status().name(), transfer.createdAt(), transfer.acceptedAt());
678	    }
679	
680	    private EscalationView toEscalationView(Escalation escalation) {
681	        return new EscalationView(escalation.id(), escalation.deadlineAt(), escalation.triggeredAt(),
682	                escalation.triggeredCommander(), escalation.status().name(), escalation.note(),
683	                escalation.acknowledgedBy(), escalation.acknowledgedAt(), escalation.createdAt());
684	    }
685	
686	    /**
687	     * 组装升级查询视图：current 为该事件当前（唯一）升级记录，无则 null。
688	     */
689	    private EscalationHistoryView toEscalationHistory(Incident incident, List<Escalation> list) {
690	        List<EscalationView> views = list.stream().map(this::toEscalationView).toList();
691	        EscalationView current = views.isEmpty() ? null : views.get(views.size() - 1);
692	        return new EscalationHistoryView(incident.deadlineAt(), current, views);
693	    }
694	}
